package io.colorsand.core

/**
 * The colors a unit of sand can have.
 *
 * [code] is the single letter used to write levels as text, [rgb] is a suggested display color (0xRRGGBB)
 * so every frontend renders the same palette.
 */
enum class SandColor(val code: Char, val rgb: Int) {
    RED('R', 0xE53935),
    ORANGE('O', 0xFB8C00),
    YELLOW('Y', 0xFDD835),
    GREEN('G', 0x43A047),
    BLUE('B', 0x1E88E5),
    PURPLE('P', 0x8E24AA),
    PINK('K', 0xEC407A),
    CYAN('C', 0x00ACC1),
    BROWN('N', 0x6D4C41),
    LIME('L', 0xC0CA33),
    GRAY('A', 0x9E9E9E),
    WHITE('W', 0xF5F5F5);

    companion object {
        fun fromCode(code: Char): SandColor =
            entries.firstOrNull { it.code == code.uppercaseChar() }
                ?: throw IllegalArgumentException("Unknown sand color code '$code'")
    }
}
