package io.colorsand.ui.hud

import androidx.compose.material3.LocalTextStyle
import androidx.compose.material3.ProvideTextStyle
import androidx.compose.runtime.Composable
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.font.FontWeight
import io.colorsand.resources.Res
import io.colorsand.resources.fredoka_bold
import io.colorsand.resources.fredoka_semibold
import org.jetbrains.compose.resources.Font

/**
 * Fredoka, the round display font of the HUD's titles and buttons. Every heavy weight maps to its bold cut, so
 * nothing gets synthesized; lighter text uses the semibold one.
 */
@Composable
fun gameFont(): FontFamily {
    val bold = Res.font.fredoka_bold
    return FontFamily(
        Font(Res.font.fredoka_semibold, FontWeight.Normal),
        Font(Res.font.fredoka_semibold, FontWeight.Medium),
        Font(Res.font.fredoka_semibold, FontWeight.SemiBold),
        Font(bold, FontWeight.Bold),
        Font(bold, FontWeight.ExtraBold),
        Font(bold, FontWeight.Black),
    )
}

/** Sets [gameFont] for all text in [content]. */
@Composable
fun WithGameFont(content: @Composable () -> Unit) {
    ProvideTextStyle(LocalTextStyle.current.copy(fontFamily = gameFont()), content)
}
