package io.colorsand.ui

import io.colorsand.core.Stars

/** The best stars earned on each level, stored as text like "1:3,2:2". Unreadable entries are skipped. */
data class StarBook(val best: Map<Int, Int> = emptyMap()) {
    operator fun get(level: Int): Int = best[level] ?: 0

    val total: Int get() = best.values.sum()

    /** This book with [stars] for [level], unless the level already has as many. */
    fun record(level: Int, stars: Int): StarBook =
        if (stars <= this[level]) this else StarBook(best + (level to stars.coerceIn(1, Stars.MAX)))

    fun encode(): String = best.entries.sortedBy { it.key }.joinToString(",") { "${it.key}:${it.value}" }

    companion object {
        fun decode(text: String?): StarBook = StarBook(
            text.orEmpty().split(',').mapNotNull { entry ->
                val (level, stars) = entry.split(':').takeIf { it.size == 2 } ?: return@mapNotNull null
                val l = level.trim().toIntOrNull()?.takeIf { it >= 1 } ?: return@mapNotNull null
                val s = stars.trim().toIntOrNull()?.takeIf { it in 1..Stars.MAX } ?: return@mapNotNull null
                l to s
            }.toMap(),
        )
    }
}
